using namespace std;

int main() {
    long long n, m, magic, mod;
    cin >> n >> m >> magic >> mod;
    auto flower = [&](long long i, long long j) { return (i + j * magic) % mod % 2 == 1; };
    vector<long long> rows(n, 0), cols(m, 0);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (flower(i, j)) { rows[i]++; cols[j]++; }
    // every L shape has a unique corner cell
    long long answer = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
