import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        long magic = sc.nextLong(), mod = sc.nextLong();
        boolean[][] flower = new boolean[n][m];
        long[] rows = new long[n], cols = new long[m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if ((i + j * magic) % mod % 2 == 1) { flower[i][j] = true; rows[i]++; cols[j]++; }
        // every L shape has a unique corner cell
        long answer = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (flower[i][j]) answer += (rows[i] - 1) * (cols[j] - 1);
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var n, m, magic, mod int
	fmt.Scan(&n, &m, &magic, &mod)
	flower := func(i, j int) bool { return (i+j*magic)%mod%2 == 1 }
	rows := make([]int, n)
	cols := make([]int, m)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if flower(i, j) {
				rows[i]++
				cols[j]++
			}
		}
	}
	// every L shape has a unique corner cell
	answer := 0
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if flower(i, j) {
				answer += (rows[i] - 1) * (cols[j] - 1)
			}
		}
	}
	fmt.Println(answer)
}
